mapper.select:
SELECT * FROM (
    SELECT temp.*, ROWNUM row_num FROM (
        SELECT
            ,
            c.ID AS C_ID, c.NAME AS C_NAME, c.ID_CARD AS C_ID_CARD, c.PHONE AS C_PHONE,
            c.EMAIL AS C_EMAIL, c.GENDER AS C_GENDER, c.AGE AS C_AGE,
            c.ADDRESS AS C_ADDRESS, c.OCCUPATION AS C_OCCUPATION, c.PATIENT_ID AS C_PATIENT_ID,
            ft.ID AS FT_ID, ft.TYPE_NAME AS FT_TYPE_NAME, ft.TYPE_CODE AS FT_TYPE_CODE,
            ft.SLA_DAYS AS FT_SLA_DAYS, ft.SLA_HOURS AS FT_SLA_HOURS, ft.DESCRIPTION AS FT_DESCRIPTION,
            d.ID AS D_ID, d.DEPT_NAME AS D_DEPT_NAME, d.DEPT_CODE AS D_DEPT_CODE,
            u.ID AS U_ID, u.USERNAME AS U_USERNAME, u.REAL_NAME AS U_REAL_NAME, u.PHONE AS U_PHONE
        FROM T_FEEDBACK f
        LEFT JOIN T_COMPLAINANT c ON f.COMPLAINANT_ID = c.ID AND c.DEL_FLAG = 0
        LEFT JOIN T_FEEDBACK_TYPE ft ON f.FEEDBACK_TYPE_ID = ft.ID AND ft.DEL_FLAG = 0
        LEFT JOIN SYS_DEPT d ON f.DEPT_ID = d.ID AND d.DEL_FLAG = 0
        LEFT JOIN SYS_USER u ON f.HANDLER_ID = u.ID AND u.DEL_FLAG = 0
        WHERE f.DEL_FLAG = 0

            AND f.FEEDBACK_NO LIKE '%' || #{feedbackNo} || '%'


            AND f.TITLE LIKE '%' || #{title} || '%'


            AND f.FEEDBACK_TYPE_ID = #{feedbackTypeId}


            AND f.SOURCE = #{source}


            AND f.PRIORITY = #{priority}


            AND f.STATUS = #{status}


            AND f.DEPT_ID = #{deptId}


            AND f.HANDLER_ID = #{handlerId}


            AND f.CREATE_TIME >= TO_DATE(#{startDate}, 'YYYY-MM-DD')


            AND f.CREATE_TIME <= TO_DATE(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')


            AND (f.TITLE LIKE '%' || #{keyword} || '%' OR f.CONTENT LIKE '%' || #{keyword} || '%')

        ORDER BY f.CREATE_TIME DESC
    ) temp WHERE ROWNUM <= #{endRow}
) WHERE row_num > #{startRow}

mapper.update:
UPDATE T_FEEDBACK
TITLE = #{title}, CONTENT = #{content}, FEEDBACK_TYPE_ID = #{feedbackTypeId}, COMPLAINANT_ID = #{complainantId}, SOURCE = #{source}, PRIORITY = #{priority}, STATUS = #{status}, DEPT_ID = #{deptId}, HANDLER_ID = #{handlerId}, SLA_DEADLINE = #{slaDeadline}, SLA_WARNING_TIME = #{slaWarningTime}, IS_ANONYMOUS = #{isAnonymous}, CONTACT_PHONE = #{contactPhone}, CONTACT_EMAIL = #{contactEmail}, RATING = #{rating}, RATING_COMMENT = #{ratingComment}, UPDATE_BY = #{updateBy}, UPDATE_TIME = #{updateTime}, DEL_FLAG = #{delFlag}, REMARK = #{remark},
WHERE ID = #{id}
